package org.sigf.app;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import javafx.application.Application; import javafx.application.Platform; import javafx.concurrent.Task; import javafx.fxml.FXMLLoader; import javafx.geometry.Insets; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage;
public class Main extends Application {
 private Database db; private Stage stage; private Scene scene;
 @Override public void start(Stage stage){this.stage=stage;scene=new Scene(new StackPane(),1050,700);scene.getStylesheets().add(Main.class.getResource("/css/style.css").toExternalForm());stage.setTitle("SIGF · Gestión farmacéutica");stage.setMinWidth(850);stage.setMinHeight(600);stage.setScene(scene);stage.show();String url=System.getenv("SIGF_DB_URL"),user=System.getenv("SIGF_DB_USER"),pass=System.getenv("SIGF_DB_PASSWORD");if(url!=null&&!url.isBlank()&&user!=null&&!user.isBlank()&&pass!=null&&!pass.isEmpty()){connect(url,user,pass,null);}else connectionForm("");}
 private VBox card(String heading,String detail){VBox box=new VBox(14);box.setMaxWidth(510);box.setMaxHeight(Region.USE_PREF_SIZE);box.setPadding(new Insets(35,40,35,40));box.getStyleClass().add("login-card");Label brand=new Label("SIGF / FARMACIA");brand.getStyleClass().add("eyebrow");Label title=new Label(heading);title.getStyleClass().add("hero");Label text=new Label(detail);text.setWrapText(true);text.getStyleClass().add("muted");box.getChildren().addAll(brand,title,text);return box;}
 private void showCard(VBox box){StackPane root=new StackPane(box);root.getStyleClass().add("login-background");scene.setRoot(root);}
 private void connectionForm(String error){VBox box=card("Conectar base de datos","Conéctate a la base exclusiva sigf_javafx_db. La contraseña no se guarda en el equipo.");TextField host=new TextField("127.0.0.1"),port=new TextField("5432"),user=new TextField("sigf_app");PasswordField password=new PasswordField();password.setPromptText("Contraseña de sigf_app");Label message=new Label(error);message.setWrapText(true);message.getStyleClass().add("warning");Button button=new Button("Conectar");button.getStyleClass().add("primary");button.setMaxWidth(Double.MAX_VALUE);button.setId("connectButton");host.setId("dbHost");port.setId("dbPort");user.setId("dbUser");password.setId("dbPassword");button.setOnAction(e->{try{String h=host.getText().trim();int p=Integer.parseInt(port.getText().trim());if(!h.matches("[A-Za-z0-9.-]+")||p<1||p>65535)throw new IllegalArgumentException("Servidor o puerto inválido");String name=user.getText().trim(),secret=password.getText();if(name.isEmpty()||secret.isEmpty())throw new IllegalArgumentException("Ingrese usuario y contraseña");button.setDisable(true);message.setText("Conectando y verificando la base…");connect("jdbc:postgresql://"+h+":"+p+"/sigf_javafx_db",name,secret,()->{password.clear();button.setDisable(false);});}catch(Exception ex){message.setText(ex.getMessage());}});password.setOnAction(e->button.fire());box.getChildren().addAll(new Label("Servidor"),host,new Label("Puerto"),port,new Label("Usuario PostgreSQL"),user,new Label("Contraseña PostgreSQL"),password,button,message);showCard(box);}
 private void connect(String url,String username,String password,Runnable failed){Task<Database> t=new Task<>(){protected Database call(){return new Database(url,username,password);}};t.setOnSucceeded(e->{db=t.getValue();if("true".equalsIgnoreCase(System.getenv("SIGF_BOOTSTRAP"))){bootstrapFromEnvironment();return;}Task<Boolean> check=new Task<>(){protected Boolean call()throws Exception{return new Security(db).hasUsers();}};check.setOnSucceeded(x->{if(check.getValue())loginForm();else administratorForm("");});check.setOnFailed(x->{db.close();db=null;connectionForm("No se pudo verificar el administrador: "+message(check.getException()));});startTask(check);});t.setOnFailed(e->{if(failed!=null)failed.run();connectionForm("No se pudo conectar. Verifique el usuario, la contraseña y los permisos de la base. "+message(t.getException()));});startTask(t);}
 private void bootstrapFromEnvironment(){Task<Void> t=new Task<>(){protected Void call()throws Exception{new Security(db).bootstrap(System.getenv("SIGF_ADMIN_USER"),System.getenv("SIGF_ADMIN_PASSWORD"));return null;}};t.setOnSucceeded(e->{System.out.println("Administrador creado. Desactive SIGF_BOOTSTRAP y reinicie.");Platform.exit();});t.setOnFailed(e->{new Alert(Alert.AlertType.ERROR,message(t.getException())).showAndWait();Platform.exit();});startTask(t);}
 private void administratorForm(String error){VBox box=card("Crear administrador","Primera configuración: crea el usuario administrador de SIGF. Es diferente del usuario PostgreSQL.");TextField name=new TextField();PasswordField password=new PasswordField(),confirm=new PasswordField();name.setId("adminUser");password.setId("adminPassword");confirm.setId("adminConfirm");Label msg=new Label(error);msg.getStyleClass().add("warning");msg.setWrapText(true);Button save=new Button("Crear administrador");save.getStyleClass().add("primary");save.setMaxWidth(Double.MAX_VALUE);save.setOnAction(e->{String n=name.getText().trim(),p=password.getText();if(!p.equals(confirm.getText())){msg.setText("Las contraseñas no coinciden");return;}if(n.isBlank()||p.length()<12){msg.setText("Ingrese un usuario y una contraseña de al menos 12 caracteres");return;}save.setDisable(true);msg.setText("Creando administrador…");Task<Void> task=new Task<>(){protected Void call()throws Exception{new Security(db).bootstrap(n,p);return null;}};task.setOnSucceeded(x->{password.clear();confirm.clear();loginForm();});task.setOnFailed(x->{password.clear();confirm.clear();save.setDisable(false);msg.setText(message(task.getException()));});startTask(task);});box.getChildren().addAll(new Label("Usuario de SIGF"),name,new Label("Contraseña (mínimo 12 caracteres)"),password,new Label("Confirmar contraseña"),confirm,save,msg);showCard(box);}
 private void loginForm(){try{FXMLLoader loader=new FXMLLoader(Main.class.getResource("/fxml/login.fxml"));Parent root=loader.load();((LoginController)loader.getController()).init(stage,db);scene.setRoot(root);}catch(Exception e){new Alert(Alert.AlertType.ERROR,message(e)).showAndWait();Platform.exit();}}
 private static void startTask(Task<?> task){Thread t=new Thread(task,"sigf-startup");t.setDaemon(true);t.start();}private static String message(Throwable e){return e==null?"Error desconocido":java.util.Objects.toString(e.getMessage(),"Error desconocido");}
 @Override public void stop(){if(db!=null)db.close();}public static void main(String[]args){launch(args);}
}
